INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'disaster', 'n.', '/dɪˈzɑːstə(r)/', '灾难;灾害', 'An earthquake is a terrible natural disaster.', '地震是一种可怕的自然灾害。', 'Natural Disasters', 1, 0, 'senior', 'wordlist', 'required1', 'U4', 'a natural disaster', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tornado', 'n.', '/tɔːˈneɪdəʊ/', '龙卷风;旋风', 'A powerful tornado swept through the town.', '一场强龙卷风席卷了小镇。', 'Natural Disasters', 2, 0, 'senior', 'wordlist', 'required1', 'U4', 'a powerful tornado', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'drought', 'n.', '/draʊt/', '旱灾;久旱', 'The long drought destroyed most of the crops.', '长期干旱毁掉了大部分庄稼。', 'Natural Disasters', 3, 0, 'senior', 'wordlist', 'required1', 'U4', 'a long drought', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'flood', 'n./v.', '/flʌd/', '洪水;淹没;大量涌入', 'The flood covered the streets with water.', '洪水把街道淹没在水中。', 'Natural Disasters', 4, 0, 'senior', 'wordlist', 'required1', 'U4', 'a terrible flood', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tsunami', 'n.', '/tsuːˈnɑːmi/', '海啸', 'The earthquake caused a huge tsunami.', '这场地震引发了巨大的海啸。', 'Natural Disasters', 5, 0, 'senior', 'wordlist', 'required1', 'U4', 'a huge tsunami', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'magnitude', 'n.', '/ˈmæɡnɪtjuːd/', '(地震)震级;巨大;重要性', 'The quake reached a magnitude of 7.8.', '这次地震达到了7.8级。', 'Natural Disasters', 6, 0, 'senior', 'wordlist', 'required1', 'U4', 'a magnitude of 7.8', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rescue', 'v./n.', '/ˈreskjuː/', '营救;救援', 'Rescue workers dug people out of the ruins.', '救援人员把人们从废墟中挖出来。', 'Natural Disasters', 7, 0, 'senior', 'wordlist', 'required1', 'U4', 'rescue workers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'damage', 'v./n.', '/ˈdæmɪdʒ/', '损害;破坏;损失', 'The storm caused great damage to the village.', '风暴对村庄造成了巨大破坏。', 'Natural Disasters', 8, 0, 'senior', 'wordlist', 'required1', 'U4', 'cause damage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'destroy', 'vt.', '/dɪˈstrɔɪ/', '摧毁;毁灭', 'The earthquake destroyed almost every building.', '地震几乎摧毁了每一栋建筑。', 'Natural Disasters', 9, 0, 'senior', 'wordlist', 'required1', 'U4', 'destroy buildings', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'evacuate', 'vt.', '/ɪˈvækjueɪt/', '疏散;撤离', 'The police evacuated the people from the area.', '警方将人们从该地区疏散。', 'Natural Disasters', 10, 0, 'senior', 'wordlist', 'required1', 'U4', 'evacuate the area', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'shelter', 'n./v.', '/ˈʃeltə(r)/', '避难处;居所;庇护;躲避', 'Workers built shelters for the survivors.', '工人们为幸存者搭建了避难所。', 'Natural Disasters', 11, 0, 'senior', 'wordlist', 'required1', 'U4', 'build shelters', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'survive', 'v.', '/səˈvaɪv/', '生存;幸存;艰难度过', 'Only a few people survived the disaster.', '只有少数人在灾难中幸存。', 'Natural Disasters', 12, 0, 'senior', 'wordlist', 'required1', 'U4', 'survive the quake', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'survivor', 'n.', '/səˈvaɪvə(r)/', '幸存者', 'Food and water were brought to the survivors.', '食物和水被送到幸存者手中。', 'Natural Disasters', 13, 0, 'senior', 'wordlist', 'required1', 'U4', 'help the survivors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'shock', 'n./v.', '/ʃɒk/', '震惊;令人震惊的事;休克;(使)震惊', 'People stood in shock as they looked at the ruins.', '人们望着废墟,震惊得说不出话。', 'Natural Disasters', 14, 0, 'senior', 'wordlist', 'required1', 'U4', 'in shock', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ruin', 'n./v.', '/ˈruːɪn/', '废墟;毁坏;破坏', 'In one minute the whole city lay in ruins.', '一分钟之内整座城市变成了废墟。', 'Natural Disasters', 15, 0, 'senior', 'wordlist', 'required1', 'U4', 'in ruins', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'brick', 'n.', '/brɪk/', '砖;砖块', 'Fallen bricks covered the ground like red leaves.', '掉落的砖块像红叶一样铺满地面。', 'Natural Disasters', 16, 0, 'senior', 'wordlist', 'required1', 'U4', 'fallen bricks', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'metal', 'n.', '/ˈmetl/', '金属', 'The railway tracks became useless pieces of metal.', '铁轨变成了无用的金属碎片。', 'Natural Disasters', 17, 0, 'senior', 'wordlist', 'required1', 'U4', 'pieces of metal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'trap', 'vt./n.', '/træp/', '使陷入险境;困住;陷阱', 'Soldiers dug out those who were trapped.', '士兵们把被困的人挖了出来。', 'Natural Disasters', 18, 0, 'senior', 'wordlist', 'required1', 'U4', 'be trapped', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'bury', 'vt.', '/ˈberi/', '埋葬;掩埋', 'They worked hard to bury the dead with respect.', '他们尽力庄重地安葬逝者。', 'Natural Disasters', 19, 0, 'senior', 'wordlist', 'required1', 'U4', 'bury the dead', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'breathe', 'v.', '/briːð/', '呼吸', 'Slowly, the city began to breathe again.', '慢慢地,这座城市又开始呼吸了。', 'Natural Disasters', 20, 0, 'senior', 'wordlist', 'required1', 'U4', 'breathe again', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'revive', 'v.', '/rɪˈvaɪv/', '复活;(使)苏醒;振兴', 'Tangshan started to revive itself after the quake.', '地震后唐山开始重新振作。', 'Natural Disasters', 21, 0, 'senior', 'wordlist', 'required1', 'U4', 'revive itself', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unify', 'v.', '/ˈjuːnɪfaɪ/', '统一;(使)成一体', 'In times of disaster, people must unify.', '在灾难时刻,人们必须团结一致。', 'Natural Disasters', 22, 0, 'senior', 'wordlist', 'required1', 'U4', 'unify and rebuild', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wisdom', 'n.', '/ˈwɪzdəm/', '智慧;才智', 'The people showed great wisdom in rebuilding.', '人们在重建中展现了非凡的智慧。', 'Natural Disasters', 23, 0, 'senior', 'wordlist', 'required1', 'U4', 'show wisdom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'suffer', 'v.', '/ˈsʌfə(r)/', '遭受;蒙受;受苦', 'People who suffered the quake needed help.', '遭受地震的人们需要帮助。', 'Natural Disasters', 24, 0, 'senior', 'wordlist', 'required1', 'U4', 'suffer a disaster', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'volcano', 'n.', '/vɒlˈkeɪnəʊ/', '火山', 'The couple lived near an active volcano.', '这对夫妇住在一座活火山附近。', 'Natural Disasters', 25, 0, 'senior', 'wordlist', 'required1', 'U4', 'an active volcano', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'erupt', 'v.', '/ɪˈrʌpt/', '(火山)爆发;喷出', 'They volunteered to help after the volcano erupted.', '火山爆发后他们主动帮忙。', 'Natural Disasters', 26, 0, 'senior', 'wordlist', 'required1', 'U4', 'the volcano erupted', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'typhoon', 'n.', '/taɪˈfuːn/', '台风', 'A strong typhoon hit the coast last summer.', '去年夏天一场强台风袭击了海岸。', 'Natural Disasters', 27, 0, 'senior', 'wordlist', 'required1', 'U4', 'a strong typhoon', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hurricane', 'n.', '/ˈhʌrɪkən/', '飓风', 'Most buildings damaged by the hurricane were repaired.', '被飓风损坏的大多数建筑都修好了。', 'Natural Disasters', 28, 0, 'senior', 'wordlist', 'required1', 'U4', 'the hurricane hit', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'supply', 'n./vt.', '/səˈplaɪ/', '供应(量);补给品;供给', 'An emergency supply of food reached the area.', '一批应急食品运到了该地区。', 'Natural Disasters', 29, 0, 'senior', 'wordlist', 'required1', 'U4', 'an emergency supply', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'deliver', 'v.', '/dɪˈlɪvə(r)/', '递送;传达;发表', 'Damaged roads made it hard to deliver food.', '受损的道路使送食物变得困难。', 'Natural Disasters', 30, 0, 'senior', 'wordlist', 'required1', 'U4', 'deliver food', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'emergency', 'n.', '/iˈmɜːdʒənsi/', '突发事件;紧急情况', 'Call an emergency number in an emergency.', '紧急情况下要拨打急救电话。', 'Natural Disasters', 31, 0, 'senior', 'wordlist', 'required1', 'U4', 'in an emergency', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'calm', 'adj./v.', '/kɑːm/', '镇静的;沉着的;(使)平静', 'During a disaster, the most important thing is to stay calm.', '灾难中最重要的是保持镇静。', 'Natural Disasters', 32, 0, 'senior', 'wordlist', 'required1', 'U4', 'stay calm', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'aid', 'n./v.', '/eɪd/', '援助;帮助;救援物资', 'Foreign aid was organised for the affected area.', '为受灾地区组织了外国援助。', 'Natural Disasters', 33, 0, 'senior', 'wordlist', 'required1', 'U4', 'first aid', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'affect', 'vt.', '/əˈfekt/', '影响;(疾病)侵袭;深深打动', 'Half a million people were affected by the flood.', '五十万人受到这场洪水的影响。', 'Natural Disasters', 34, 0, 'senior', 'wordlist', 'required1', 'U4', 'be affected by', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'effect', 'n.', '/ɪˈfekt/', '影响;结果;效果', 'The effects of the disaster lasted for years.', '这场灾难的影响持续了数年。', 'Natural Disasters', 35, 0, 'senior', 'wordlist', 'required1', 'U4', 'the effects of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'crash', 'v./n.', '/kræʃ/', '碰撞;撞击;撞车', 'Huge waves crashed into the coastline.', '巨浪猛烈拍打着海岸线。', 'Natural Disasters', 36, 0, 'senior', 'wordlist', 'required1', 'U4', 'crash into', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sweep', 'v.', '/swiːp/', '打扫;清扫;席卷;消灭', 'Homes and cars were swept away by the waves.', '房屋和汽车被海浪卷走。', 'Natural Disasters', 37, 0, 'senior', 'wordlist', 'required1', 'U4', 'sweep away', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wave', 'n./v.', '/weɪv/', '海浪;波浪;挥手', 'Huge waves reached the village in seconds.', '巨浪几秒钟就到了村子。', 'Natural Disasters', 38, 0, 'senior', 'wordlist', 'required1', 'U4', 'huge waves', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'strike', 'v./n.', '/straɪk/', '侵袭;击打;罢工', 'The undersea quake struck early in the morning.', '海底地震在清晨发生。', 'Natural Disasters', 39, 0, 'senior', 'wordlist', 'required1', 'U4', 'the quake struck', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'percent', 'n.', '/pəˈsent/', '百分之……', 'Ninety percent of the homes were gone.', '百分之九十的房屋消失了。', 'Natural Disasters', 40, 0, 'senior', 'wordlist', 'required1', 'U4', 'ninety percent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'power', 'n.', '/ˈpaʊə(r)/', '电力供应;能量;力量;权力', 'After the quake, water, food and power were hard to get.', '地震后,水、食物和电都很难得到。', 'Natural Disasters', 41, 0, 'senior', 'wordlist', 'required1', 'U4', 'power supply', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'electricity', 'n.', '/ɪˌlekˈtrɪsəti/', '电;电能', 'The town was left without electricity for days.', '小镇断电了好几天。', 'Natural Disasters', 42, 0, 'senior', 'wordlist', 'required1', 'U4', 'without electricity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'effort', 'n.', '/ˈefət/', '努力;艰难的尝试', 'With the tireless efforts of its people, a new city was built.', '凭着人们不懈的努力,一座新城建了起来。', 'Natural Disasters', 43, 0, 'senior', 'wordlist', 'required1', 'U4', 'tireless efforts', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'injure', 'vt.', '/ˈɪndʒə(r)/', '使受伤;损害', 'Two thirds of the people were dead or injured.', '三分之二的人死亡或受伤。', 'Natural Disasters', 44, 0, 'senior', 'wordlist', 'required1', 'U4', 'be injured', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u4.01', '①指人:who(主格)/ whom(宾格·介词后)', 'A2', 10, '必修一 U4 — 先行词指人:作从句主语用 who;作宾语、尤其紧跟介词时用 whom(to/with/for whom)。', 1, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u4.02', '②指物:which / that(及 that 必用情形)', 'A2', 10, '必修一 U4 — 先行词指物用 which/that;先行词被 all/everything/nothing/the only/序数词/最高级 等修饰,或为不定代词时只能用 that;介词后只能用 which(不可 that)。', 2, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u4.03', '③whose(所属)+ 介词 + whom / which', 'A2', 10, '必修一 U4 — 表所属关系用 whose(指人或物);介词提到从句句首时,指人用 whom、指物用 which。', 3, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.01'), '"The villagers ____ lived near the river were warned in time."', 'who', 'which', 'whom', 'whose', 'A', '先行词 villagers 指人、作从句主语 → who。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.01'), '"The soldiers ____ dug out the survivors worked for days."', 'which', 'who', 'whom', 'whose', 'B', '指人作主语 → who。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.01'), '"Doctors and nurses ____ came to help saved many lives."', 'which', 'whom', 'who', 'whose', 'C', '指人作主语 → who。', 2, 3, 'mcq');
