INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.03'), '"The plane from ____ the aid was dropped flew very low."', 'that', 'which', 'who', 'whose', 'B', '介词 from 后指物 → which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.03'), '"The nurse to ____ the boy owed his life visited him later."', 'who', 'which', 'whom', 'whose', 'C', '介词 to 后指人 → whom。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U4' AND code='u4.03'), '"The family ____ car was swept away had to walk to safety."', 'who', 'which', 'that', 'whose', 'D', '表所属(family 的 car)→ whose。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Night the Earth Didn''t Sleep', 'At 3:42 a.m. on 28 July 1976, everything in Tangshan began to shake. It seemed as if the world were coming to an end. One of the most deadly earthquakes of the 20th century had begun, and even Beijing, 150 kilometres away, felt the shock. A huge crack, eight kilometres long, cut across houses, roads and waterways. In less than one minute, a large city lay in ruins. Two thirds of the people who lived there were dead or injured, and thousands of children were left without parents. About ninety percent of the homes and all of the hospitals were gone. Bricks covered the ground like red autumn leaves. People stood in shock, and then, later that afternoon, another big quake struck the city again. Water, food and electricity were all hard to get, and people began to wonder how long the disaster would last.', '记叙·唐山大地震', 145, '[{"q":"How long did it take for the city to be ruined?","answer":"A","options":["Less than a minute.","About an hour.","A whole day.","Several weeks."],"explanation":"原文 ''In less than one minute, a large city lay in ruins'' 的转述。"},{"q":"What made the situation even worse that afternoon?","answer":"B","options":["The weather suddenly turned cold.","A second strong quake hit the city.","The river dried up completely.","The army left the city."],"explanation":"原文 ''another big quake struck the city again''(后半段,覆盖不同位置)。"},{"q":"What were people worried about after the quakes?","answer":"A","options":["Whether the disaster would soon come to an end.","How to leave the country.","How to find their cars.","Where to go shopping."],"explanation":"末句 ''wonder how long the disaster would last'' 的转述。"}]'::jsonb, '[{"word":"ruin","cn":"废墟"},{"word":"crack","cn":"裂缝"},{"word":"shock","cn":"震惊"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Strange Signs Before the Quake', 'For several days before the Tangshan earthquake, strange things were happening in the countryside. The water in the village wells rose and fell, again and again. Deep cracks appeared in the well walls, and at least one well gave off a strange smelly gas. Chickens and even pigs were too nervous to eat, and dogs refused to go inside buildings. Mice ran out of the fields looking for places to hide, and fish jumped out of the water. At about 3 a.m., bright lights were seen in the sky outside the city, and loud noises were heard. But the city''s one million people were asleep as usual that night, and no one understood what these signs meant. Today, scientists study such warning signs carefully, hoping that one day they may help to save lives.', '说明·地震预兆', 134, '[{"q":"What happened to the water in the village wells?","answer":"B","options":["It turned into ice.","It rose and fell many times.","It became sweet to drink.","It stayed completely still."],"explanation":"原文 ''rose and fell, again and again'' 的转述。"},{"q":"How did the animals behave before the quake?","answer":"C","options":["They slept more than usual.","They became friendlier to people.","They acted nervous and tried to hide.","They ate much more food."],"explanation":"原文 animals ''too nervous to eat… mice ran out… fish jumped out'' 的概括。"},{"q":"Why didn''t the people react to the signs?","answer":"D","options":["They were busy working.","They had already left the city.","They thought the signs were a joke.","They were asleep and did not understand them."],"explanation":"原文 ''were asleep as usual… no one understood what these signs meant''(后段)。"}]'::jsonb, '[{"word":"crack","cn":"裂缝"},{"word":"gas","cn":"气体"},{"word":"sign","cn":"迹象"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Tsunami Hits Asia', 'On 26 December 2004, the most powerful earthquake in forty years struck under the sea off the coast of Indonesia. The quake reached a magnitude of 9.0 and caused a huge tsunami that crashed into coastlines across Asia. Fishermen, tourists, homes and cars were swept away by the giant waves. More than six thousand five hundred people were killed in several countries, and over a million more were affected. In Sri Lanka, far from the quake centre, the waves still reached the shore and destroyed whole villages. Thousands of people were missing, and the number of deaths was expected to grow. Foreign aid was quickly organised for the tsunami-hit countries, but dangerous conditions and damaged roads made it very hard to deliver food and supplies to the survivors.', '新闻·亚洲海啸', 128, '[{"q":"What caused the tsunami?","answer":"A","options":["A powerful undersea earthquake.","A volcanic eruption.","A strong typhoon.","Heavy rain for weeks."],"explanation":"原文 ''earthquake… caused a huge tsunami'' 的转述。"},{"q":"What happened in Sri Lanka, far from the quake centre?","answer":"B","options":["Nothing serious happened there.","The waves still destroyed whole villages.","Only a few boats were lost.","The earthquake was not felt at all."],"explanation":"原文 ''far from the quake centre, the waves still reached the shore and destroyed whole villages''。"},{"q":"Why was it difficult to help the survivors?","answer":"C","options":["There were no volunteers.","No country wanted to help.","Damaged roads made delivering supplies hard.","The survivors refused all aid."],"explanation":"末句 ''damaged roads made it very hard to deliver food and supplies''(后段)。"}]'::jsonb, '[{"word":"tsunami","cn":"海啸"},{"word":"magnitude","cn":"震级"},{"word":"sweep away","cn":"卷走"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Tangshan Rises Again', 'Hope was not lost after the Tangshan earthquake. Soon after the quakes, the army sent more than a hundred thousand soldiers to dig out those who were trapped and to care for the injured. Thousands of doctors and nurses arrived to provide medical care, and water and food were brought into the city by train, truck and plane. Workers built shelters for survivors whose homes had been destroyed. Slowly, the city began to breathe again. With strong support from the government and the tireless efforts of its people, a new Tangshan was built upon the ruins. Today the new city is home to more than seven million people, with great improvements in transport, industry and the environment. Tangshan has proved to the world that, in times of disaster, people must unify and show the wisdom to stay positive and rebuild for a brighter future.', '记叙·唐山重建', 144, '[{"q":"What did the soldiers do first when they arrived?","answer":"D","options":["They rebuilt the factories.","They opened new shops.","They left the city quickly.","They dug out trapped people and helped the injured."],"explanation":"原文 ''dig out those who were trapped and to care for the injured''。"},{"q":"How was the new Tangshan built?","answer":"A","options":["Through government support and the people''s efforts.","By foreign companies alone.","Without any government help.","By moving the whole city away."],"explanation":"原文 ''with strong support from the government and the tireless efforts of its people''(后段)。"},{"q":"What lesson does Tangshan show the world?","answer":"B","options":["Disasters can never be survived.","That people should come together and rebuild with hope.","It is best to leave ruined cities empty.","Only money can rebuild a city."],"explanation":"末句 ''people must unify and show the wisdom to stay positive and rebuild'' 的转述。"}]'::jsonb, '[{"word":"shelter","cn":"避难所"},{"word":"unify","cn":"团结"},{"word":"revive","cn":"复苏"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Be Ready for a Disaster', 'No one can stop a natural disaster, but we can all prepare for one. The most important thing during any disaster is to stay calm. Before an earthquake, make a safety list and decide where to meet your family. Keep an emergency kit on hand, with enough water and food for three days, a radio, a flashlight and a first aid kit. During an earthquake indoors, remember to drop, cover and hold on. If you are outdoors, move to an open space away from buildings and power lines. If you are trapped after a quake, do not shout for a long time, because that wastes your energy. Instead, tap on a pipe or wall, or use a whistle, so that rescue workers can find you. A little preparation today may save your life tomorrow.', '说明·防灾准备', 134, '[{"q":"What is the most important thing during a disaster?","answer":"C","options":["To run as fast as possible.","To take photos.","To stay calm.","To call your friends."],"explanation":"原文 ''The most important thing… is to stay calm''。"},{"q":"What should you do during an earthquake if you are indoors?","answer":"D","options":["Run outside at once.","Stand near the window.","Use the lift to leave.","Drop down, cover your head, and hold on."],"explanation":"原文 ''drop, cover and hold on''。"},{"q":"Why should a trapped person tap on a pipe instead of shouting for long?","answer":"A","options":["Shouting for long wastes energy.","Shouting is not allowed.","Tapping is more fun.","Pipes can move on their own."],"explanation":"原文 ''do not shout for a long time, because that wastes your energy… tap on a pipe''(后段)。"}]'::jsonb, '[{"word":"emergency","cn":"紧急情况"},{"word":"whistle","cn":"哨子"},{"word":"first aid kit","cn":"急救箱"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Rescue Worker''s Diary', 'My name is Lin, and I am a rescue worker. When the news of the earthquake came, my team and I left within an hour. The roads were so badly damaged that we had to walk the last few kilometres. Everywhere we looked, there was nothing but ruins. We worked day and night, digging carefully so that we would not hurt the people trapped below. On the second day, we heard a faint tapping on a broken pipe. We followed the sound and found a little girl whose leg was hurt but who was still alive. When we lifted her out, the whole street cheered. Moments like that gave us the strength to keep going. A disaster takes away so much, but it also shows how brave and kind ordinary people can be.', '记叙·救援者日记', 133, '[{"q":"Why did the team have to walk the last few kilometres?","answer":"B","options":["They had no cars at all.","The roads were too badly damaged to drive on.","They wanted some exercise.","The city was closed to visitors."],"explanation":"原文 ''roads were so badly damaged that we had to walk''。"},{"q":"How did they find the little girl?","answer":"C","options":["She shouted for help loudly.","A dog led them to her.","They traced a soft tapping sound coming from a pipe.","She walked out by herself."],"explanation":"原文 ''heard a faint tapping on a broken pipe… followed the sound''(中段)。"},{"q":"What does the writer learn from the disaster?","answer":"D","options":["That rescue work is easy.","That disasters can be prevented.","That cities should not be rebuilt.","That ordinary people can be brave and kind."],"explanation":"末句 ''shows how brave and kind ordinary people can be'' 的转述。"}]'::jsonb, '[{"word":"rescue","cn":"救援"},{"word":"trap","cn":"困住"},{"word":"brave","cn":"勇敢的"}]'::jsonb, 2, 'required1', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'A Letter After the Quake', 'Dear Aunt, I am writing to tell you that we are safe. Last week a strong earthquake (1)____ our town in the middle of the night. In less than a minute many houses lay in (2)____. We were lucky, because our building did not (3)____ down. At first everyone was in (4)____ and did not know what to do. Then soldiers and doctors (5)____ to help us. They dug out the people who were (6)____ under the broken walls. Workers built (7)____ for the families whose homes were gone. Water and food were (8)____ into the town by truck. Slowly, life is starting to return to (9)____. Please do not worry about us. With the (10)____ of so many kind people, we will rebuild our home. Love, Mei', 128, 2, '[{"q":"1","answer":"A","options":["hit","left","kept","sold"],"explanation":"earthquake hit our town 地震袭击。"},{"q":"2","answer":"B","options":["water","ruins","trees","boxes"],"explanation":"lay in ruins 成废墟。"},{"q":"3","answer":"C","options":["stand","grow","fall","look"],"explanation":"fall down 倒塌。"},{"q":"4","answer":"D","options":["love","peace","fun","shock"],"explanation":"in shock 震惊。"},{"q":"5","answer":"A","options":["came","left","failed","refused"],"explanation":"came to help 前来帮忙。"},{"q":"6","answer":"B","options":["happy","trapped","ready","calm"],"explanation":"trapped 被困。"},{"q":"7","answer":"C","options":["gardens","markets","shelters","schools"],"explanation":"build shelters 搭避难所。"},{"q":"8","answer":"D","options":["thrown","lost","hidden","brought"],"explanation":"brought into the town 运进城。"},{"q":"9","answer":"A","options":["normal","danger","winter","silence"],"explanation":"return to normal 恢复正常。"},{"q":"10","answer":"B","options":["noise","help","money","fear"],"explanation":"with the help of 在……帮助下。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'Flood News Report', 'Heavy rain fell for three days, and on Sunday a terrible (1)____ covered the whole valley. The river rose so fast that many families had no time to (2)____ their homes. By Monday, half a million people had been (3)____ by the water. Rescue teams used boats and (4)____ to reach those who were stuck on roofs. The government quickly (5)____ shelters and provided food and clean water. Sadly, more than eighty people lost their (6)____. Foreign (7)____ was organised for the flood-hit area, but damaged roads made it hard to (8)____ supplies. Experts say that planting more trees may help to (9)____ such floods in the future. For now, the most important thing is to keep everyone (10)____ and dry.', 121, 2, '[{"q":"1","answer":"C","options":["fire","wind","flood","ice"],"explanation":"a terrible flood 洪水。"},{"q":"2","answer":"D","options":["build","clean","paint","leave"],"explanation":"leave their homes 离开家。"},{"q":"3","answer":"A","options":["affected","saved","invited","praised"],"explanation":"affected by the water 受影响。"},{"q":"4","answer":"B","options":["books","helicopters","tickets","phones"],"explanation":"boats and helicopters 船和直升机。"},{"q":"5","answer":"C","options":["closed","sold","set up","broke"],"explanation":"set up shelters 设立避难所。"},{"q":"6","answer":"D","options":["books","jobs","pets","lives"],"explanation":"lose one''s life 丧生。"},{"q":"7","answer":"A","options":["aid","noise","food","music"],"explanation":"foreign aid 外国援助。"},{"q":"8","answer":"B","options":["forget","deliver","waste","hide"],"explanation":"deliver supplies 运送物资。"},{"q":"9","answer":"C","options":["cause","enjoy","prevent","watch"],"explanation":"prevent such floods 预防洪水。"},{"q":"10","answer":"D","options":["rich","busy","late","safe"],"explanation":"keep everyone safe 保证安全。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'Before a Storm Comes', 'When a typhoon is coming, a little (1)____ can keep your family safe. First of all, listen to the (2)____ on the radio or TV so that you know when the storm will (3)____. Bring inside anything that the strong wind could blow (4)____. Make sure you have an emergency (5)____ ready, with water, food, a flashlight and a first aid kit. During the storm, stay (6)____ and away from windows. Do not go (7)____ unless it is really necessary. If the power goes (8)____, use a flashlight instead of candles. Most importantly, stay (9)____ and follow the instructions of the local officials. After the storm passes, be careful of broken glass and fallen (10)____ wires. Being prepared is the best way to protect the people you love.', 128, 2, '[{"q":"1","answer":"A","options":["preparation","noise","money","luck"],"explanation":"a little preparation 一点准备。"},{"q":"2","answer":"B","options":["music","news","story","song"],"explanation":"listen to the news 听新闻。"},{"q":"3","answer":"C","options":["sleep","smile","arrive","sing"],"explanation":"when the storm will arrive 何时到来。"},{"q":"4","answer":"D","options":["up","down","on","away"],"explanation":"blow away 吹走。"},{"q":"5","answer":"A","options":["kit","game","book","ticket"],"explanation":"emergency kit 急救/应急包。"},{"q":"6","answer":"B","options":["outside","indoors","alone","awake"],"explanation":"stay indoors 待在室内。"},{"q":"7","answer":"C","options":["inside","upstairs","outside","home"],"explanation":"go outside 外出。"},{"q":"8","answer":"D","options":["up","in","off","out"],"explanation":"the power goes out 停电。"},{"q":"9","answer":"A","options":["calm","loud","busy","late"],"explanation":"stay calm 保持镇静。"},{"q":"10","answer":"B","options":["water","power","phone","train"],"explanation":"fallen power wires 倒落的电线。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'A Rescue Dog Named Lucky', 'Lucky is not an ordinary dog; he is a (1)____ dog. After the big earthquake, he went into the (2)____ with his owner, Mrs Fors, to look for survivors. Lucky uses his nose to (3)____ people who are trapped deep under the broken walls. One cold morning, he suddenly stopped and began to (4)____ at the ground. The workers dug carefully and found a man who was still (5)____. Everyone (6)____ when the man was lifted out alive. Lucky has helped to (7)____ many lives this way. He is never (8)____ of the danger, and he works until he is too tired to move. After a hard day, his (9)____ gives him a big meal and a warm bed. To the survivors and their families, brave little Lucky is a real (10)____.', 132, 2, '[{"q":"1","answer":"C","options":["guard","farm","rescue","show"],"explanation":"a rescue dog 救援犬。"},{"q":"2","answer":"D","options":["garden","shop","river","ruins"],"explanation":"go into the ruins 进入废墟。"},{"q":"3","answer":"A","options":["find","feed","wash","teach"],"explanation":"find people 找到人。"},{"q":"4","answer":"B","options":["sleep","dig","sing","jump"],"explanation":"begin to dig 开始刨。"},{"q":"5","answer":"C","options":["asleep","afraid","alive","angry"],"explanation":"still alive 仍活着。"},{"q":"6","answer":"D","options":["cried","left","slept","cheered"],"explanation":"everyone cheered 欢呼。"},{"q":"7","answer":"A","options":["save","lose","waste","end"],"explanation":"save lives 拯救生命。"},{"q":"8","answer":"B","options":["proud","afraid","sure","fond"],"explanation":"never afraid of danger 不怕危险。"},{"q":"9","answer":"C","options":["teacher","doctor","owner","driver"],"explanation":"his owner 他的主人。"},{"q":"10","answer":"D","options":["problem","stranger","enemy","hero"],"explanation":"a real hero 真正的英雄。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'Building the Town Again', 'A year after the earthquake, our town looks very (1)____ from before. Where there were once ruins, new houses now (2)____. The government gave strong (3)____, and people from all over the country came to (4)____. My father, who lost his shop, has (5)____ a new one near the square. The new buildings are designed to be earthquake-(6)____, so we feel much safer now. Of course, we will never (7)____ those who died, and we still miss them. But we have learned that a disaster cannot (8)____ a people who refuse to give up. Out of (9)____ for all the help we received, many young people in our town now want to study medicine or join the army, so that they can (10)____ others one day.', 126, 2, '[{"q":"1","answer":"A","options":["different","boring","quiet","cheap"],"explanation":"look different 看上去不同。"},{"q":"2","answer":"B","options":["fall","stand","sleep","break"],"explanation":"new houses stand 新房矗立。"},{"q":"3","answer":"C","options":["noise","weather","support","trouble"],"explanation":"give support 给予支持。"},{"q":"4","answer":"D","options":["leave","watch","rest","help"],"explanation":"came to help 前来帮忙。"},{"q":"5","answer":"A","options":["opened","lost","closed","sold"],"explanation":"opened a new one 开了新店。"},{"q":"6","answer":"B","options":["afraid","safe","famous","slow"],"explanation":"earthquake-safe 抗震的。"},{"q":"7","answer":"C","options":["meet","thank","forget","save"],"explanation":"never forget those who died 永不忘记。"},{"q":"8","answer":"D","options":["help","teach","join","beat"],"explanation":"cannot beat a people 打不垮。"},{"q":"9","answer":"A","options":["gratitude","fear","anger","surprise"],"explanation":"out of gratitude 出于感激。"},{"q":"10","answer":"B","options":["hurt","help","follow","leave"],"explanation":"help others 帮助他人。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U4', 'Why We Study Disasters', 'Natural disasters have always been part of life on Earth, so why do scientists (1)____ them so carefully? The main reason is to save (2)____. By studying earthquakes, scientists hope to find warning (3)____ that can give people time to escape. By tracking a tsunami across the sea, they can (4)____ the people on the coast before the waves (5)____. Studying past disasters also helps engineers build stronger houses that are less likely to (6)____ down. Of course, no one can completely (7)____ a natural disaster from happening. But the more we (8)____, the better we can prepare. When the next disaster (9)____, knowledge and preparation may be the difference between (10)____ and death. That is why this kind of research matters to us all.', 125, 2, '[{"q":"1","answer":"C","options":["forget","enjoy","study","hide"],"explanation":"study them carefully 仔细研究。"},{"q":"2","answer":"D","options":["money","time","books","lives"],"explanation":"save lives 拯救生命。"},{"q":"3","answer":"A","options":["signs","songs","games","prices"],"explanation":"warning signs 预警信号。"},{"q":"4","answer":"B","options":["thank","warn","follow","teach"],"explanation":"warn the people 警告人们。"},{"q":"5","answer":"C","options":["sleep","smile","arrive","rest"],"explanation":"before the waves arrive 海浪到来前。"},{"q":"6","answer":"D","options":["grow","stand","wake","fall"],"explanation":"fall down 倒塌。"},{"q":"7","answer":"A","options":["stop","start","watch","enjoy"],"explanation":"stop a disaster 阻止灾难。"},{"q":"8","answer":"B","options":["lose","know","fear","waste"],"explanation":"the more we know 知道得越多。"},{"q":"9","answer":"C","options":["ends","sleeps","strikes","leaves"],"explanation":"the next disaster strikes 灾难来袭。"},{"q":"10","answer":"D","options":["noise","money","fun","life"],"explanation":"between life and death 生与死之间。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 An Earthquake News Report', '必修一 U4 · dialogue', 3, 'Anchor: We are now joined by our reporter near the disaster area. What can you tell us?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 The City That Rose Again', '必修一 U4 · passage', 2, 'In 1976, a deadly earthquake destroyed almost all of Tangshan.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 Making an Emergency Kit', '必修一 U4 · dialogue', 3, 'Student: Mrs Fors, what should we keep in an emergency kit?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 During an Earthquake', '必修一 U4 · passage', 2, 'If an earthquake happens while you are indoors, do not run outside at once.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 A Survivor''s Story', '必修一 U4 · dialogue', 3, 'Reporter: You survived the earthquake. How did you feel that night?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 A Tip for Disaster Safety', '必修一 U4 · passage', 2, 'Here is a simple tip that may one day save your life.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Summary(写一篇摘要)', 'A Travel Email', '假设你叫李华。请用英语为下面这则新闻写一篇约80词的摘要,要点包括:① 何时何地发生了什么灾难;② 造成的主要影响(伤亡/破坏);③ 救援与援助情况。注意:摘要只写主要信息,不抄原句、不加细节或个人评论。
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required1', 'U4', '{"title":"限制性定语从句·关系代词 速查","intro":"关系代词替代先行词、在从句里作主语/宾语/定语。判断用哪个:先看指人还是指物,再看在从句中作什么成分。","table":{"headers":["关系代词","用法 / 例句"],"rows":[["who","指人·作主语:The people who lived here were warned."],["whom","指人·作宾语/介词后:the doctor with whom he worked"],["which","指物·作主/宾语;介词后只能 which:the path along which they escaped"],["that","指人或物;不定代词/最高级/序数词/the only 后只能 that"],["whose","表所属(人或物):survivors whose homes were destroyed"]]},"specialRules":[{"rule":"先行词被 all/everything/nothing/the only/序数词/最高级 修饰 → 只能用 that","mark":"the only building that…"},{"rule":"介词紧跟关系代词:指人 whom、指物 which,都不可用 that","mark":"in which / with whom"},{"rule":"that 不能放在介词后,也不能引导非限制性定语从句","mark":"× the city in that"},{"rule":"whose 既可指人也可指物(= of which / of whom)","mark":"the town whose buildings…"}],"why":["限制性定语从句对先行词起限定作用,不能去掉、前面不加逗号;关系代词在从句里一定充当某个成分(主语/宾语/定语)。"],"gaokaoPoints":["who/whom/which/that/whose 辨析、that 必用情形、介词+which/whom;语法填空与单选高频。","指人作宾语口语可用 who,但介词紧跟时必须 whom。"],"examVsReal":[{"exam":"the man with whom I spoke（考试/正式）","real":"the man I spoke with / the man who I spoke with","note":"考试用 with whom;口语常把介词后置、甚至省略关系代词"},{"exam":"the people who helped us（考试更稳）","real":"the people that helped us","note":"考试用 who 指人;口语里 that 指人也很常见"}]}'::jsonb);
